(() => {
 if(document.querySelector('.about-chat'))return;
 const root=new URL('./',document.currentScript.src);
 const panel=document.createElement('aside');panel.className='about-chat';panel.id='about-chat';panel.inert=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Know more about Vinny');
 panel.innerHTML='<header><div><span class="chat-mark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="currentColor" aria-hidden="true" focusable="false"><path fill="currentColor" stroke="none" style="fill:currentColor;stroke:none" d="M13 1h6v8l5.657-5.657 4.243 4.243L23.243 13H31v6h-7.757l5.657 5.414-4.243 4.243L19 23v8h-6v-8l-5.657 5.657L3.1 24.414 8.757 19H1v-6h7.757L3.1 7.586l4.243-4.243L13 9Z"/></svg></span><h2>Know more about me</h2></div><button type="button" class="chat-close" aria-label="Close chat"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="chat-log" role="log" aria-label="Conversation" aria-live="polite" aria-relevant="additions"><div class="chat-space"><span class="chat-spark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="currentColor" aria-hidden="true" focusable="false"><path fill="currentColor" stroke="none" style="fill:currentColor;stroke:none" d="M13 1h6v8l5.657-5.657 4.243 4.243L23.243 13H31v6h-7.757l5.657 5.414-4.243 4.243L19 23v8h-6v-8l-5.657 5.657L3.1 24.414 8.757 19H1v-6h7.757L3.1 7.586l4.243-4.243L13 9Z"/></svg></span><h3>A little more Vinny.</h3><p>The portfolio version of me. A little craft, a little attitude. What would you like to know?</p></div></div><form class="chat-composer"><label for="about-chat-prompt">Ask me something</label><div><input id="about-chat-prompt" name="question" maxlength="600" autocomplete="off" placeholder="What would you like to know?" disabled><button type="submit" aria-label="Send message" disabled>↑</button></div><small>Curated public profile · Replies stay on this page</small></form>';
 document.body.append(panel);let previous=null;const background=new Map();const mobile=matchMedia('(max-width:760px)');
 panel.addEventListener('transitionend',e=>{if(e.target===panel&&e.propertyName==='transform')window.dispatchEvent(new Event('resize'))});
 async function open(trigger){previous=trigger;await window.portfolioCloseMobileMenu?.();document.querySelectorAll('.contact-dropdown.is-open').forEach(e=>{e.classList.remove('is-open');e.querySelector('[data-contact-trigger]')?.setAttribute('aria-expanded','false');e.querySelector('.contact-options').inert=true});document.querySelectorAll('.top-contact.is-open').forEach(e=>e.classList.remove('is-open'));document.querySelectorAll('.about-top-nav details').forEach(e=>e.open=false);panel.inert=false;if(mobile.matches){panel.setAttribute('aria-modal','true');[...document.body.children].filter(e=>e!==panel&&!['SCRIPT','STYLE','LINK'].includes(e.tagName)).forEach(e=>{background.set(e,e.inert);e.inert=true})}document.body.classList.add('chat-open');document.querySelectorAll('[data-about-chat]').forEach(e=>e.setAttribute('aria-expanded','true'));panel.querySelector('.chat-close').focus({preventScroll:true});}
 function close(){background.forEach((value,e)=>e.inert=value);background.clear();panel.removeAttribute('aria-modal');document.body.classList.remove('chat-open');panel.inert=true;document.querySelectorAll('[data-about-chat]').forEach(e=>e.setAttribute('aria-expanded','false'));previous?.focus({preventScroll:true});}
 const log=panel.querySelector('.chat-log'),form=panel.querySelector('form'),input=panel.querySelector('input'),send=form.querySelector('button');let lastTopic=null,busy=false;
 function message(role,text){const article=document.createElement('article');article.className='chat-message chat-message-'+role;article.setAttribute('aria-label',role==='user'?'You':'Portfolio guide');const p=document.createElement('p');p.textContent=text;article.append(p);log.append(article);while(log.querySelectorAll('.chat-message').length>40)log.querySelector('.chat-message').remove();return article}
 async function ask(text){if(busy||!window.VinnyChat||!text.trim())return;busy=true;send.disabled=true;panel.querySelector('.chat-space')?.remove();message('user',text.trim());input.value='';const answer=window.VinnyChat.reply(text,lastTopic);if(answer.id)lastTopic=answer.id;
  const typing=document.createElement('div');typing.className='chat-typing';typing.setAttribute('role','status');typing.setAttribute('aria-label','Thinking');typing.innerHTML='<span aria-hidden="true"></span><span aria-hidden="true"></span><span aria-hidden="true"></span>';log.append(typing);form.setAttribute('aria-busy','true');log.scrollTop=log.scrollHeight;
  await new Promise(resolve=>setTimeout(resolve,900+Math.random()*650+Math.min(answer.text.length,300)));
  typing.remove();form.removeAttribute('aria-busy');const article=message('assistant',answer.text);
  if(answer.links.length){const links=document.createElement('div');links.className='chat-work-links';answer.links.forEach(([label,path])=>{const link=document.createElement('a');link.textContent=label;link.href=new URL(path,root).href;if(path.startsWith('https:')){link.target='_blank';link.rel='noopener noreferrer'}links.append(link)});article.append(links)}
  if(answer.sources.length){const details=document.createElement('details');details.className='chat-sources';const summary=document.createElement('summary');summary.textContent='Sources';details.append(summary);answer.sources.forEach(source=>{const link=document.createElement('a');link.textContent=source.label;link.href=source.href;link.target='_blank';link.rel='noopener noreferrer';details.append(link)});article.append(details)}
  busy=false;send.disabled=!input.value.trim();log.scrollTop+=article.getBoundingClientRect().top-log.getBoundingClientRect().top-12;
 }
 form.addEventListener('submit',e=>{e.preventDefault();ask(input.value)});input.addEventListener('input',()=>send.disabled=busy||!input.value.trim());
 const knowledge=document.createElement('script');knowledge.src=new URL('about-chat-knowledge.js?v=5',root).href;knowledge.onload=()=>{input.disabled=false};knowledge.onerror=()=>{form.querySelector('small').textContent='The guide could not load. Please refresh to try again.'};document.head.append(knowledge);
 panel.querySelector('.chat-close').addEventListener('click',close);
 document.addEventListener('keydown',e=>{if(e.key==='Tab'&&mobile.matches&&document.body.classList.contains('chat-open')){const items=[...panel.querySelectorAll('button:not(:disabled),input:not(:disabled),a[href],summary')].filter(el=>el.getClientRects().length);const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if(e.key==='Escape'&&document.body.classList.contains('chat-open')){e.preventDefault();close()}});
 document.addEventListener('click',e=>{const t=e.target.closest('[data-about-chat]');if(t){e.preventDefault();open(t)}});
 function addTriggers(){document.querySelectorAll('.contact-options,.top-contact-options,.about-top-nav details>div').forEach(menu=>{if(menu.querySelector('[data-about-chat]'))return;const button=document.createElement('button');button.type='button';button.className='chat-menu-trigger';button.dataset.aboutChat='';button.setAttribute('aria-controls','about-chat');button.setAttribute('aria-expanded','false');button.innerHTML='<span>Know more about me</span><small>A little conversation</small>';menu.append(button)});}
 addTriggers();new MutationObserver(addTriggers).observe(document.body,{childList:true,subtree:true});
 if(document.body.classList.contains('about-page')){const h1=document.querySelector('main h1');if(h1){const button=document.createElement('button');button.type='button';button.className='about-chat-entry';button.dataset.aboutChat='';button.setAttribute('aria-controls','about-chat');button.setAttribute('aria-expanded','false');button.textContent='Know more about me';h1.insertAdjacentElement('afterend',button)}}
})();
